<?php
namespace App\Http\Controllers; use App\Models\Admin; use Illuminate\Http\Request; use Illuminate\Support\Facades\Artisan; use Illuminate\Support\Facades\Hash; use Illuminate\Support\Str;
class InstallController extends Controller { private function lock(){return storage_path('app/installed.lock');} public function form(){abort_if(file_exists($this->lock()),404);return view('install');} public function install(Request $r){abort_if(file_exists($this->lock()),404);$d=$r->validate(['environment'=>'required|in:development,staging,production','app_url'=>'required|url','db_host'=>'required','db_port'=>'required|integer','db_database'=>'required','db_username'=>'required','db_password'=>'nullable','firebase_project_id'=>'required','firebase_credentials'=>'required','admin_name'=>'required','admin_email'=>'required|email','admin_password'=>'required|min:10']);$env=file_get_contents(base_path('.env.'.$d['environment'].'.example'));$replace=['APP_URL'=>$d['app_url'],'DB_HOST'=>$d['db_host'],'DB_PORT'=>$d['db_port'],'DB_DATABASE'=>$d['db_database'],'DB_USERNAME'=>$d['db_username'],'DB_PASSWORD'=>$d['db_password']??'','FIREBASE_PROJECT_ID'=>$d['firebase_project_id'],'FIREBASE_CREDENTIALS'=>$d['firebase_credentials']];foreach($replace as $k=>$v)$env=preg_replace('/^'.preg_quote($k,'/').'=.*/m',$k.'='.$v,$env);file_put_contents(base_path('.env'),$env); config(['database.connections.mysql.host'=>$d['db_host'],'database.connections.mysql.port'=>$d['db_port'],'database.connections.mysql.database'=>$d['db_database'],'database.connections.mysql.username'=>$d['db_username'],'database.connections.mysql.password'=>$d['db_password']??'']); Artisan::call('key:generate',['--force'=>true]);Artisan::call('config:clear');Artisan::call('migrate',['--force'=>true,'--seed'=>true]);$admin=Admin::create(['name'=>$d['admin_name'],'email'=>$d['admin_email'],'password'=>Hash::make($d['admin_password']),'is_active'=>true]); $role=\App\Models\Role::where('slug','super-admin')->first(); if($role)$admin->roles()->sync([$role->id]);file_put_contents($this->lock(),now()->toIso8601String());return view('installed');} }
